#include <Arduino.h>
#include <WiFi.h>
#include <WebServer.h>
#include <ArduinoJson.h>
#include <Update.h>
#include "NMEAEngine.h"
#include "Settings.h"
#include "GnssLogger.h"
#include "TrackExport.h"
#include "EventEngine.h"

HardwareSerial GNSS(1),GPSOut(2);WebServer web(80);WiFiServer tcp(10110);WiFiClient clients[4];NMEAEngine nmea;SettingsManager settings;GnssLogger logger;EventEngine events;unsigned long packets=0,invalid=0,lastDataMs=0;String wifiMode="AP";
bool protectedRoute(){auto &c=settings.get();if(!c.webAuthEnabled)return true;if(web.authenticate(c.webUsername.c_str(),c.webPassword.c_str()))return true;web.requestAuthentication();return false;}
void sendJson(const JsonDocument&j){String b;serializeJson(j,b);web.send(200,"application/json",b);}
String page(){return R"HTML(<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>NavIC GPS Bridge</title><style>body{margin:0;font:15px system-ui;background:#08111f;color:#eaf2ff}.top{padding:16px;background:#0d1930}.wrap{max-width:820px;margin:auto;padding:16px}.card{background:#12223e;border:1px solid #28456f;border-radius:14px;padding:16px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.label{font-size:11px;color:#9bb0da;text-transform:uppercase}.value{font-size:22px;font-weight:700;margin-top:5px}input,select,button{width:100%;box-sizing:border-box;padding:10px;margin:6px 0;border-radius:8px;border:1px solid #38547d;background:#09172b;color:#fff}button{cursor:pointer;background:#1c5f9e}small{color:#9bb0da}.ok{color:#62e6a3}.bad{color:#ff7891}</style></head><body><div class=top><b>🛰 NavIC GPS Bridge</b></div><main class=wrap><div class=grid><div class=card><div class=label>Fix</div><div id=fix class=value>—</div></div><div class=card><div class=label>Position</div><div id=pos class=value>—</div></div><div class=card><div class=label>Satellites</div><div id=sat class=value>—</div></div><div class=card><div class=label>Speed</div><div id=speed class=value>—</div></div></div><div class=card><b>Configuration</b><input id=ssid placeholder="Wi-Fi SSID"><input id=stap type=password placeholder="Wi-Fi password (leave blank to keep)"><input id=gb type=number placeholder="GNSS baud"><input id=ob type=number placeholder="Output baud"><input id=port type=number placeholder="TCP port"><label><input id=ap type=checkbox> Keep device AP enabled</label><label><input id=sta type=checkbox> Join configured Wi-Fi</label><label><input id=compat type=checkbox> GPS compatibility conversion</label><button onclick=save()>Save configuration</button><small id=cfg></small></div><div class=card><b>Maintenance</b><button onclick=post('/api/restart')>Restart device</button><button onclick=post('/api/track/clear')>Clear track</button><button onclick=ota()>OTA firmware update</button><input id=bin type=file accept=.bin style="display:none" onchange=upload()><small id=maint></small></div></main><script>async function load(){let d=await(await fetch('/api/live')).json();fix.textContent=d.fix?'VALID FIX':'NO FIX';fix.className='value '+(d.fix?'ok':'bad');pos.textContent=d.latitude.toFixed(6)+', '+d.longitude.toFixed(6);sat.textContent=d.satellites;speed.textContent=d.speed_kmh.toFixed(1)+' km/h'}async function config(){let c=await(await fetch('/api/config')).json();ssid.value=c.sta_ssid;gb.value=c.gnss_baud;ob.value=c.gps_out_baud;port.value=c.tcp_port;ap.checked=c.ap_enabled;sta.checked=c.sta_enabled;compat.checked=c.gps_compatibility}async function save(){let r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sta_ssid:ssid.value,sta_password:stap.value,gnss_baud:+gb.value,gps_out_baud:+ob.value,tcp_port:+port.value,ap_enabled:ap.checked,sta_enabled:sta.checked,gps_compatibility:compat.checked})});let d=await r.json();cfg.textContent=d.ok?'Saved. Restart required to apply hardware/network changes.':d.error}async function post(u){let r=await fetch(u,{method:'POST'});maint.textContent=await r.text()}function ota(){bin.click()}async function upload(){if(!bin.files[0])return;let f=new FormData();f.append('update',bin.files[0]);let r=await fetch('/api/ota',{method:'POST',body:f});maint.textContent=await r.text()}load();config();setInterval(load,1000)</script></body></html>)HTML";}
void live(){auto&d=nmea.data();JsonDocument j;j["fix"]=d.fix;j["latitude"]=d.latitude;j["longitude"]=d.longitude;j["altitude"]=d.altitude;j["speed_kmh"]=d.speedKmh;j["satellites"]=d.satellites;j["hdop"]=d.hdop;j["last_nmea"]=d.lastSentence;j["packets"]=packets;j["data_fresh"]=millis()-lastDataMs<3000;sendJson(j);}
void configGet(){auto&c=settings.get();JsonDocument j;j["gnss_baud"]=c.gnssBaud;j["gps_out_baud"]=c.gpsOutBaud;j["tcp_port"]=c.tcpPort;j["gps_compatibility"]=c.gpsCompatibility;j["ap_enabled"]=c.apEnabled;j["sta_enabled"]=c.staEnabled;j["sta_ssid"]=c.staSsid;j["web_auth_enabled"]=c.webAuthEnabled;j["web_username"]=c.webUsername;sendJson(j);}
void configPost(){JsonDocument j;if(deserializeJson(j,web.arg("plain"))){web.send(400,"application/json","{\"ok\":false,\"error\":\"invalid_json\"}");return;}BridgeConfig c=settings.get();if(j["gnss_baud"].is<uint32_t>())c.gnssBaud=j["gnss_baud"];if(j["gps_out_baud"].is<uint32_t>())c.gpsOutBaud=j["gps_out_baud"];if(j["tcp_port"].is<uint16_t>())c.tcpPort=j["tcp_port"];if(j["gps_compatibility"].is<bool>())c.gpsCompatibility=j["gps_compatibility"];if(j["ap_enabled"].is<bool>())c.apEnabled=j["ap_enabled"];if(j["sta_enabled"].is<bool>())c.staEnabled=j["sta_enabled"];if(j["sta_ssid"].is<String>())c.staSsid=j["sta_ssid"].as<String>();if(j["sta_password"].is<String>()&&j["sta_password"].as<String>().length())c.staPassword=j["sta_password"].as<String>();if(c.gnssBaud<1200||c.gnssBaud>921600||c.gpsOutBaud<1200||c.gpsOutBaud>921600||c.tcpPort<1024){web.send(422,"application/json","{\"ok\":false,\"error\":\"invalid_settings\"}");return;}settings.save(c);web.send(200,"application/json","{\"ok\":true,\"restart_required\":true}");}
void setupWifi(){auto&c=settings.get();bool ap=c.apEnabled;if(c.staEnabled&&c.staSsid.length()){WiFi.mode(ap?WIFI_AP_STA:WIFI_STA);WiFi.begin(c.staSsid.c_str(),c.staPassword.c_str());unsigned long start=millis();while(WiFi.status()!=WL_CONNECTED&&millis()-start<10000)delay(100);if(WiFi.status()==WL_CONNECTED)wifiMode=ap?"AP+STA":"STA";else wifiMode=ap?"AP":"OFFLINE";}else{WiFi.mode(ap?WIFI_AP:WIFI_OFF);wifiMode=ap?"AP":"OFFLINE";}if(ap)WiFi.softAP("NavIC-GPS-Bridge","navicgps");}
void restartDevice(){web.send(200,"application/json","{\"ok\":true}");delay(300);ESP.restart();}
void setup(){Serial.begin(115200);settings.begin();auto&c=settings.get();GNSS.begin(c.gnssBaud,SERIAL_8N1,16,17);GPSOut.begin(c.gpsOutBaud,SERIAL_8N1,-1,18);setupWifi();tcp.begin(c.tcpPort);web.on("/",[]{if(protectedRoute())web.send(200,"text/html",page());});web.on("/api/live",[]{if(protectedRoute())live();});web.on("/api/config",HTTP_GET,[]{if(protectedRoute())configGet();});web.on("/api/config",HTTP_POST,[]{if(protectedRoute())configPost();});web.on("/api/restart",HTTP_POST,[]{if(protectedRoute())restartDevice();});web.on("/api/track/clear",HTTP_POST,[]{if(protectedRoute()){logger.clear();web.send(200,"application/json","{\"ok\":true}");}});web.on("/api/ota",HTTP_POST,[]{web.send(200,"text/plain",Update.hasError()?"OTA failed":"OTA successful. Restarting…");delay(300);if(!Update.hasError())ESP.restart();},[]{HTTPUpload&u=web.upload();if(u.status==UPLOAD_FILE_START)Update.begin(UPDATE_SIZE_UNKNOWN);else if(u.status==UPLOAD_FILE_WRITE)Update.write(u.buf,u.currentSize);else if(u.status==UPLOAD_FILE_END)Update.end(true);});web.begin();}
void loop(){web.handleClient();WiFiClient incoming=tcp.available();if(incoming)for(auto&c:clients)if(!c||!c.connected()){c=incoming;break;}while(GNSS.available()){String l=GNSS.readStringUntil('\n');l.trim();if(!l.length())continue;if(!nmea.process(l)){invalid++;continue;}packets++;lastDataMs=millis();auto&d=nmea.data();logger.add(d.latitude,d.longitude,d.altitude,d.speedKmh,millis());events.update(d,true,millis());String o=settings.get().gpsCompatibility?nmea.gpsCompatible(l):l;GPSOut.println(o);for(auto&c:clients)if(c&&c.connected())c.println(o);}events.update(nmea.data(),millis()-lastDataMs<3000,millis());}